 private val blue=Color.rgb(25,111,220);private val teal=Color.rgb(0,145,135);private val green=Color.rgb(25,145,78);private val navy=Color.rgb(24,58,92);private val amber=Color.rgb(220,145,20);private val red=Color.rgb(190,55,55);private val bg=Color.rgb(238,248,253)
 private var photoUri:Uri?=null;private var docUri:Uri?=null;private var otp="";private var fileKind=""
 private fun dp(x:Int)=(x*resources.displayMetrics.density).toInt();private fun gd(c:Int=Color.WHITE,s:Int=Color.rgb(190,210,225))=GradientDrawable().apply{setColor(c);setStroke(dp(1),s);cornerRadius=dp(16).toFloat()};private fun t(x:String,z:Float=16f,c:Int=navy)=TextView(this).apply{text=x;textSize=z;setTextColor(c);setPadding(dp(4),dp(4),dp(4),dp(4))};private fun e(h:String,max:Int=0,num:Boolean=false)=EditText(this).apply{hint=h;textSize=16f;setSingleLine(true);setPadding(dp(13),dp(8),dp(13),dp(8));background=gd();if(max>0)filters=arrayOf(InputFilter.LengthFilter(max));if(num)inputType=InputType.TYPE_CLASS_NUMBER;imeOptions=EditorInfo.IME_ACTION_NEXT};private fun b(x:String,c:Int=blue,a:()->Unit)=Button(this).apply{text=x;isAllCaps=false;textSize=14f;setTextColor(Color.WHITE);background=gd(c,c);setOnClickListener{a()}};private fun put(r:LinearLayout,v:View,h:Int=54){r.addView(v,LinearLayout.LayoutParams(-1,dp(h)).apply{setMargins(0,dp(3),0,dp(3))})};private fun show(r:LinearLayout){setContentView(ScrollView(this).apply{isFillViewport=true;addView(r)});window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE)};private fun toast(x:String)=Toast.makeText(this,x,Toast.LENGTH_LONG).show();private fun money(x:Double)="₹"+String.format(Locale.US,"%,.2f",x)
 override fun onCreate(s:Bundle?){super.onCreate(s);db=V32DatabaseHelper(this);if(p.getBoolean("logged_in",false)&&!p.getString("current_mobile","").isNullOrBlank())home()else{startActivity(Intent(this,LoginActivity::class.java));finish()}}
